<script setup lang="ts">
import { ravenTrophies,ravenSolution,castleRunes,trapEyes,castleSequence,bookPositions,trapLocations,tombRockSymbols,tombDoorSelection,castleImage,tombImage,romanNumerals } from '~/utils/bo6CastleTomb.mjs'
import CastleTombGlyph from './CastleTombGlyph.vue'
const props=defineProps<{tool:string}>()
const {state,change,undo,reset,canUndo,saveError}=usePuzzleState(props.tool)
const confirmReset=ref(false)
const uid=useId()
const isRaven=computed(()=>props.tool==='bo6-citadelle-raven')
const isCastle=computed(()=>props.tool==='bo6-citadelle-symbols')
const trophy=computed(()=>ravenSolution(state.value.trophy))
const trapMode=computed(()=>state.value.mode==='traps')
const prefix=computed(()=>trapMode.value?'page':'vase')
const choices=computed(()=>trapMode.value?trapEyes:castleRunes)
const count=computed(()=>trapMode.value?4:6)
const active=computed(()=>Math.min(Number(state.value[`${prefix.value}-active`]||0),count.value-1))
const sequence=computed(()=>castleSequence(state.value,prefix.value,count.value,choices.value))
const door=computed(()=>tombDoorSelection(state.value))
const selectedRows=computed(()=>Array.from({length:4},(_,i)=>tombRockSymbols.filter(row=>row.row===i+1)))
function update(key:string,value:any){change({...state.value,[key]:value})}
function chooseSymbol(id:string){change({...state.value,[`${prefix.value}-${active.value}`]:id,[`${prefix.value}-done-${active.value}`]:false,[`${prefix.value}-active`]:String(Math.min(active.value+1,count.value-1))})}
function glyph(row:any,ring:string){return {src:castleImage('raven-sword-cypher'),width:1265,height:677,box:`${ring==='inner'?525:859} ${row.y} 130 95`,label:ring==='inner'?`${row.element}: ${row.description}`:`${row.zodiac} zodiac symbol`}}
</script>
<template>
 <div class="puzzle castle-tomb-tool">
  <template v-if="isRaven">
   <p>Choose the antiquity you collected from the Alchemical Lab. The two symbols belong together at the <strong>bottom pointer</strong> of the Tavern Cellar wheel.</p>
   <div class="choice-row trophy-choices"><button v-for="row in ravenTrophies" :key="row.id" :aria-pressed="state.trophy===row.id" @click="update('trophy',row.id)"><img :src="row.photo" :alt="row.name" width="200" height="200" loading="lazy" /><span>{{row.name}}</span></button></div>
   <section v-if="trophy" class="result" aria-live="polite"><h3>{{trophy.name}}</h3><div class="ring-pair"><div><CastleTombGlyph :glyph="glyph(trophy,'inner')" /><strong>Inner: {{trophy.element}}</strong><span>{{trophy.description}}</span></div><div><CastleTombGlyph :glyph="glyph(trophy,'outer')" /><strong>Outer: {{trophy.zodiac}}</strong><span>Match the pictured zodiac shape.</span></div></div><p>Rotate each ring until both symbols line up with the green arrow at six o’clock, then confirm in game. This is the final alignment; it is not a number of turns.</p></section>
   <p v-else class="muted" role="status">No trophy selected. The wheel has five possible solutions.</p>
   <GuideIllustrations :images="[{src:castleImage('rune-wheel'),alt:'Tavern Cellar rune wheel: align both rings at the green bottom pointer'}]" />
   <h3>After the wheel accepts your symbols</h3><p>Lead three chasing orbs into each floor portal. Keep moving beyond the portal so the orbs cross it. The portal moves from the cellar into the Tavern, then beside the pool table. Return to the wheel and collect Balmung.</p>
   <div class="checks"><label v-for="(label,i) in ['Cellar portal: three orbs','Tavern portal: three orbs','Pool-table portal: three orbs']" :key="label"><input type="checkbox" :checked="state[`portal-${i}`]" @change="update(`portal-${i}`,($event.target as HTMLInputElement).checked)" />{{label}}</label></div>
  </template>
  <template v-else-if="isCastle">
   <div class="choice-row"><button :aria-pressed="!trapMode" @click="update('mode','vases')">Six Tavern runes</button><button :aria-pressed="trapMode" @click="update('mode','traps')">Four book traps</button></div>
   <p v-if="!trapMode">Interact with each numbered Tavern bottle. Select its slot below, then choose the matching photographed rune. Shoot this sequence at the Undercroft wall; <strong>wait for the tiles to move after every shot</strong>.</p>
   <p v-else>Read the restored book in this order: <strong>top left → bottom left → top right → bottom right</strong>. Select a page, match its eye, and record the location of the matching trap in your game.</p>
   <div class="slots"><button v-for="row in sequence.rows" :key="row.index" :aria-pressed="active===row.index" @click="update(`${prefix}-active`,String(row.index))"><span>{{trapMode?`${row.index+1}. ${bookPositions[row.index]}`:`${romanNumerals[row.index]} · Bottle ${row.index+1}`}}</span><CastleTombGlyph v-if="row.symbol" :glyph="row.symbol" /><span v-else class="empty">Choose symbol</span></button></div>
   <p role="status" aria-live="polite">Editing {{trapMode?`page ${active+1} (${bookPositions[active]})`:`bottle ${romanNumerals[active]}`}}. {{sequence.filled}} / {{count}} recorded.</p>
   <div class="glyph-picker" :class="{'trap-picker':trapMode}"><button v-for="row in choices" :key="row.id" :aria-label="`Assign ${row.label} to ${trapMode?'page':'bottle'} ${active+1}`" :aria-pressed="state[`${prefix}-${active}`]===row.id" @click="chooseSymbol(row.id)"><CastleTombGlyph :glyph="row" /><span>{{row.label}}</span></button></div>
   <p class="muted">These are crops of real guide screenshots. Their positions in this picker are not the positions on your moving wall.</p>
   <div v-if="trapMode" class="trap-route"><div v-for="row in sequence.rows" :key="row.index"><label :for="`${uid}-trap-${row.index}`">{{row.index+1}} · {{bookPositions[row.index]}}<select :id="`${uid}-trap-${row.index}`" :value="state[`location-${row.index}`]" @change="update(`location-${row.index}`,($event.target as HTMLSelectElement).value)"><option value="">Find matching trap</option><option v-for="location in trapLocations" :key="location">{{location}}</option></select></label><label class="check"><input type="checkbox" :checked="state[`page-done-${row.index}`]" @change="update(`page-done-${row.index}`,($event.target as HTMLInputElement).checked)" />Symbol dimmed in book</label></div></div>
   <p v-if="trapMode" class="result">Use only the glowing eye design that matches your current page; ignore the two fully illuminated decoys. Get kills within the active trap until it shuts off and the page dims. The fourth trap is in Sitting Rooms. A saved check is your observation, not automatic game verification.</p>
   <div v-else class="checks"><label v-for="row in sequence.rows" :key="row.index"><input type="checkbox" :checked="state[`vase-done-${row.index}`]" :disabled="!row.symbol" @change="update(`vase-done-${row.index}`,($event.target as HTMLInputElement).checked)" />{{romanNumerals[row.index]}} accepted in game</label></div>
   <details><summary>{{trapMode?'See the original book':'See the original rune wall'}}</summary><GuideIllustrations :images="[{src:castleImage(trapMode?'book-pages':'symbol-board'),alt:trapMode?'Example book: the sequence in your match may differ':'All twenty photographed wall runes; their in-game positions change'}]" /></details>
  </template>
  <template v-else>
   <p>Freeze three lanterns within ten seconds, then use the Ice Staff to lower the three marked rocks in the Nexus. Select the <strong>three glyphs you actually see</strong>. Names below are visual memory aids.</p>
   <div class="glyph-picker rock-picker"><button v-for="row in tombRockSymbols" :key="row.id" :aria-pressed="!!state[row.id]" :disabled="door.selected.length===3&&!state[row.id]" @click="update(row.id,!state[row.id])"><CastleTombGlyph :glyph="row" /><span>{{row.label}}</span><small v-if="state[row.id]">Selected</small></button></div>
   <p class="result" role="status" aria-live="polite">{{door.message}}</p>
   <section v-if="door.complete"><h3>Blocked gateway — face it from the excavation side</h3><p>The door has two columns of four symbols. Shoot the three highlighted positions with the Ice Staff, matching the glyph as a final check.</p><div class="door-grid"><template v-for="(rows,index) in selectedRows" :key="index"><div v-for="row in rows" :key="row.id" :class="{selected:state[row.id]}"><CastleTombGlyph :glyph="row" /><strong>{{row.column}} · row {{row.row}}</strong><span>{{state[row.id]?'Shoot this glyph':'Leave untouched'}}</span></div></template></div><p><strong>Check before entering:</strong> successful input leaves symbols below the gateway and a safe platform with a purple orb. A reopened door alone is not proof; wrong input can drop you. Complete the orb escort with every player nearby, then interact at the central Staff altar.</p></section>
   <details><summary>Rock map and gateway reference</summary><GuideIllustrations :images="[{src:tombImage('symbols'),alt:'Verified rock glyph reference and the two-column gateway positions'},{src:tombImage('blocked-door-with-symbols'),alt:'Blocked gateway with the eight visible glyphs'}]" /><p>Reference numbers identify rocks; they are not an order to shoot. Only the three marked rocks in your game determine your selection.</p></details>
   <details><summary>Earlier Staff build: Roman numeral reminder</summary><p>Tombs / bull mural: I through VIII. Catacombs / archer mural: I through X. Shoot in ascending order. A stroke before V or X subtracts one: IV = 4; IX = 9.</p><div class="roman-strip"><span v-for="(number,i) in romanNumerals" :key="number"><strong>{{number}}</strong>{{i+1}}</span></div><GuideIllustrations :images="[{src:tombImage('tombs-illuminated-symbols'),alt:'Tombs bull mural: eight illuminated numeral targets'}]" /></details>
  </template>
  <div class="actions"><button :disabled="!canUndo" @click="undo">Undo last change</button><button @click="confirmReset=!confirmReset">Reset helper</button></div>
  <div v-if="confirmReset" class="result"><p>Clear this helper’s saved observations?</p><div class="actions"><button @click="reset();confirmReset=false">Clear observations</button><button @click="confirmReset=false">Keep observations</button></div></div>
  <p v-if="saveError" role="alert">Your browser could not save these observations. Keep this page open.</p>
  <p class="muted">Saved on this device; inline and full-page helpers share observations. Reference images: <a :href="`https://codzombiesguides.com/main-quests/black-ops-6/${isRaven||isCastle?'citadelle-des-morts':'the-tomb'}/`" target="_blank" rel="noopener noreferrer">COD Zombies Guides</a><template v-if="isRaven">; antiquity photographs: <a href="https://www.destructoid.com/how-to-unlock-the-raven-balmung-sword-in-black-ops-6-zombies/" target="_blank" rel="noopener noreferrer">Kristina Ebanez / Destructoid</a></template>.</p>
 </div>
</template>
<style scoped>
.trophy-choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(108px,1fr))}.trophy-choices button{display:flex;flex-direction:column;align-items:center;gap:.5rem;font-size:.78rem}.trophy-choices img{display:block;max-width:100%;width:120px;height:auto;aspect-ratio:1;object-fit:contain;border-radius:4px}
.castle-tomb-tool{color:var(--text);line-height:1.6;min-width:0}.castle-tomb-tool p{margin:.85rem 0}.castle-tomb-tool h3{font-size:1.05rem;margin:1rem 0 .6rem}.castle-tomb-tool button,.castle-tomb-tool input,.castle-tomb-tool select{font:inherit}.castle-tomb-tool button{min-height:44px;padding:.65rem .8rem;border:1px solid var(--line);border-radius:7px;background:var(--surface-2);color:var(--text);cursor:pointer}.castle-tomb-tool button:hover:not(:disabled),.castle-tomb-tool button[aria-pressed=true]{border-color:var(--gold);background:var(--gold-dim)}.castle-tomb-tool button:disabled{opacity:.45;cursor:default}.castle-tomb-tool :focus-visible{outline:2px solid var(--gold);outline-offset:3px}.choice-row,.actions{display:flex;flex-wrap:wrap;gap:.5rem;margin:.8rem 0}.result{padding:1rem;border:1px solid var(--line);border-radius:8px;background:var(--surface-2);margin:1rem 0}.ring-pair{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.ring-pair>div{display:flex;flex-direction:column;gap:.4rem}.ring-pair span,.muted{font-size:.8rem;color:var(--muted)}.ring-pair :deep(svg){height:105px}.checks{display:flex;flex-wrap:wrap;gap:.6rem 1.2rem}.checks label,.check{display:flex;gap:.5rem;align-items:center;min-height:44px;font-size:.82rem}.castle-tomb-tool input[type=checkbox]{accent-color:var(--gold);height:18px;width:18px;flex-shrink:0}.slots{display:grid;grid-template-columns:repeat(auto-fit,minmax(96px,1fr));gap:.5rem}.slots button{display:flex;flex-direction:column;align-items:center;font-size:.75rem;padding:.6rem .3rem;min-height:115px}.empty{display:grid;place-items:center;min-height:78px;color:var(--muted)}.glyph-picker{display:grid;grid-template-columns:repeat(auto-fit,minmax(98px,1fr));gap:.5rem}.glyph-picker button{display:flex;flex-direction:column;align-items:center;padding:.4rem;font-size:.7rem;line-height:1.35;gap:.4rem}.glyph-picker button span{min-height:2.7em}.glyph-picker small{color:var(--gold)}.trap-picker,.rock-picker{grid-template-columns:repeat(4,minmax(0,1fr))}.trap-route{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.9rem;margin-top:1rem}.trap-route label{font-size:.8rem}.castle-tomb-tool select{display:block;min-height:44px;max-width:100%;width:100%;padding:.5rem;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:6px;margin-top:.4rem}.door-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem;max-width:420px}.door-grid>div{display:flex;flex-direction:column;align-items:center;border:1px solid var(--line);padding:.5rem;opacity:.5}.door-grid>div.selected{border-color:var(--gold);background:var(--gold-dim);opacity:1}.door-grid strong{font-size:.8rem}.door-grid span{font-size:.75rem}.castle-tomb-tool summary{cursor:pointer;min-height:44px;padding:.7rem 0;color:var(--gold)}.castle-tomb-tool a{color:var(--gold)}.roman-strip{display:flex;flex-wrap:wrap;gap:.5rem}.roman-strip>span{display:flex;flex-direction:column;align-items:center;min-width:42px}.roman-strip strong{color:var(--gold)}@media(max-width:500px){.rock-picker,.trap-picker{grid-template-columns:repeat(2,minmax(0,1fr))}.slots{grid-template-columns:repeat(3,minmax(0,1fr))}.ring-pair{gap:.5rem}}
</style>
